#!/usr/bin/env python3
"""Amandemen A-49 sampai A-54 pada HANFIS_RESEARCH_MEMORY.md (tabel amandemen §4): E8, E9-E11, perbaikan criticality aset, konsolidasi protokol E7, E12-E14, pembekuan E7; memperbarui Versi dan Tanggal di kepala berkas.
Baris baru disisipkan tepat setelah baris A-48. Gagal-tertutup (A-48 dan kepala harus ada tepat sekali); idempoten (berhenti bila A-49 ada); cadangan .pre-a49.bak.  Dari akar repo.  Komit: 'memory: A-49 sampai A-54 ...'"""
import re, shutil, sys
from pathlib import Path
P = Path("HANFIS_RESEARCH_MEMORY.md"); s = P.read_text(encoding="utf-8")
if re.search(r"^\| A-49 \|", s, re.M): print("Sudah diterapkan (A-49 ada)."); sys.exit(0)
ROWS = [
 "| A-49 | 2026-10-09 | Eksperimen E8, naskah | E8 (atribusi Shapley eksak, 25 model E4-bis, K=60; uji ICE dalam dukungan data; `scripts/e8_shapley.py`): 78,9% atribusi pada x2 dan x7 (bahan label), 3,3% pada masukan lingkungan; klaim bahwa r monoton tak-menurun di setiap masukan dikoreksi (tidak berlaku umum; kemonotonan praktis hanya untuk penggerak utama); naskah subbagian E8 (komit fc1acf7) |",
 "| A-50 | 2026-10-12 | Eksperimen E9 sampai E11 (post hoc), naskah | E9 ablasi tanpa x2 dan x7 (SS terhadap CVSS -0,135 [-0,336; 0,046]); E10 pembanding informasi-minimal (SS HANFIS terhadap GBM(x2,x7) +0,606 [-0,079; 0,847]); E11 rumus bentuk-maks a+b*max(x2,c*x7) dengan c=0,10 (MSE 0,266 melawan HANFIS 0,409; SS HANFIS terhadap rumus -0,534 [-1,438; -0,208]); abstrak, Discussion, Conclusion dikoreksi: pada horizon 4 minggu HANFIS tidak terbukti lebih baik daripada rumus empat parameter, dan target tidak bergantung pada masukan lingkungan (komit 8645666, 23bd326) |",
 "| A-51 | 2026-10-12 | Data, aset | asset_criticality etcd-3-5, cilium-1-16, velero-1-15: 7, 6, 6 menjadi 5 (selaras tabel E4-bis dan kontrak [1,5]; regresi build: tabel identik 6.833 x 15, nol sel berbeda; `scripts/fix_assets_criticality.py`; komit edab2a9) |",
 "| A-52 | 2026-10-12 | Eksperimen E7, protokol | Protokol E7 dikonsolidasi: rumus bentuk-maks sebagai pembanding terdaftar (koefisien beku `protocols/E7_formula_2026-10-12.json`: a=0,1193, b=98,851, c=0,1; 5.880 baris latih); dua keluarga Holm terpisah {P7a,P7b} dan {P7e,P7f}; sensitivitas bootstrap per minggu; aturan INSUFFICIENT_EVIDENCE: hanya batas 2% atas baris minggu uji, aset yang kehilangan semua minggu uji otomatis keluar dan dilaporkan (cockroachdb diperkirakan; penyebab: status Trivy under_investigation pada CVE Red Hat baru); runner D2 `scripts/e7_d2.py`, `e7_formula.py`, `e7_freeze_check.py`, `e7_freeze_fill.py` |",
 "| A-53 | 2026-10-12 | Eksperimen E12 sampai E14 (post hoc), naskah | E12 campuran lintas-fold (rumus dengan persistence bobot 1,0; dengan HANFIS 0,91 sampai 0,98 pada 4 minggu); E13 karakteristik operasi pada jendela 6 minggu (P7e terkonfirmasi pada sekitar 35% jendela); E14 sapuan horizon 4, 8, 12 minggu: SS HANFIS terhadap rumus -0,534, -0,048, +0,039; kontrol minggu-sama (408 baris): perubahan +0,862 [0,309; 2,973]; ablasi pada 8 dan 12 minggu: masukan lain tetap tanpa informasi; naskah subbagian E14 (komit 6c6b59e) |",
 "| A-54 | 2026-10-12 | Eksperimen E7, pembekuan | E7 DIBEKUKAN: tag `e7-prereg-2026-10-12` pada komit dbed812 (2026-10-12 15:04:42 +0700; komit dasar 6c6b59e), verifikasi LOLOS untuk 23 berkas, protokol `protocols/E7_preregistration_2026-10-12.md`, teks OSF terisi dari tag (komit f5efe35); tidak ada snapshot setelah 2026-09-21 yang ditarik dan tidak ada label forward yang dihitung sebelum tag; rehearsal pindai ulang 10 target selesai dalam 11,6 detik (cache hangat; batas bawah); D2 = 2026-11-02 lewat `scripts/e7_d2.py --stage all` |",
]
m = list(re.finditer(r"^\| A-48 \|.*$", s, re.M)); h = list(re.finditer(r"Versi: 2\.27 · Tanggal: 2026-10-09", s))
if len(m) != 1 or len(h) != 1: print(f"ABORT, tidak ada yang ditulis: baris A-48 {len(m)}x, kepala {len(h)}x (harus 1 dan 1)"); sys.exit(2)
s = s[:m[0].end()] + "\n" + "\n".join(ROWS) + s[m[0].end():]
s = s.replace("Versi: 2.27 · Tanggal: 2026-10-09", "Versi: 2.28 · Tanggal: 2026-10-12", 1)
shutil.copy(P, str(P) + ".pre-a49.bak"); P.write_text(s, encoding="utf-8"); print("OK: A-49 sampai A-54 ditambahkan; versi 2.28, tanggal 2026-10-12")
